const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const california = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'California'))
    .geometry();

  const date2012_start = '2012-08-01';
  const date2012_end = '2012-08-31';
  const date2017_start = '2017-04-01';
  const date2017_end = '2017-04-30';

  // 2. Data Acquisition & Check
  // For 2012: Use GLDAS (SMAP not available until 2015)
  // For 2017: Use SMAP

  const gldas2012 = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
    .filterDate(date2012_start, date2012_end)
    .filterBounds(california)
    .select('SoilMoi0_10cm_inst');

  const size2012 = gldas2012.size().getInfo();
  console.log(`August 2012 Images: ${size2012}`);

  if (size2012 === 0) {
    console.log('No data for August 2012.');
    console.log('<answer>C1</answer>');
    return;
  }

  const smap2017 = ee.ImageCollection('NASA_USDA/HSL/SMAP10KM_soil_moisture')
    .filterDate(date2017_start, date2017_end)
    .filterBounds(california)
    .select('ssm');

  const size2017 = smap2017.size().getInfo();
  console.log(`April 2017 Images: ${size2017}`);

  if (size2017 === 0) {
    console.log('No data for April 2017.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing
  const mean2012 = gldas2012.mean();
  const mean2017 = smap2017.mean();

  // Check pixel counts
  const count2012 = mean2012.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: california,
    scale: 3000,
    maxPixels: 1e9
  }).get('SoilMoi0_10cm_inst').getInfo();

  const count2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: california,
    scale: 3000,
    maxPixels: 1e9
  }).get('ssm').getInfo();

  console.log(`Valid pixels 2012: ${count2012}, 2017: ${count2017}`);

  if (count2012 === 0 || count2017 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation
  const val2012 = mean2012.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: california,
    scale: 3000,
    maxPixels: 1e9
  }).get('SoilMoi0_10cm_inst').getInfo();

  const val2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: california,
    scale: 3000,
    maxPixels: 1e9
  }).get('ssm').getInfo();

  console.log(`Aug 2012 soil moisture: ${val2012}`);
  console.log(`Apr 2017 soil moisture: ${val2017}`);

  // 5. Validation & Final Answer
  if (val2012 === null || val2017 === null || 
      isNaN(val2012) || isNaN(val2017) ||
      val2012 < 0 || val2017 < 0) {
    console.log('Calculation failed or invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Comparison: ${val2017.toFixed(4)} vs ${val2012.toFixed(4)}`);

  if (val2017 > val2012) {
    console.log('Soil moisture increased in April 2017.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Soil moisture did not increase in April 2017.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
